async function refreshVpnRouting(){try{vpnRoutingStatus=await api('/api/admin/vpn-routing');renderVpnRouting();await refreshVpnImportStatus()}catch(error){$('#vpnRoutingSummary').textContent=error.message;$('#vpnRoutingInstructions').textContent=''}}
async function saveVpnRouting(){const out=$('#vpnRoutingSummary');try{const result=await api('/api/admin/vpn-routing',{method:'POST',body:JSON.stringify(readVpnRoutingForm())});vpnRoutingStatus={vpn_routing:result.vpn_routing};renderVpnRouting();if(out){out.textContent=JSON.stringify(result.vpn_routing,null,2)}await refreshDeployments()}catch(error){if(out)out.textContent=error.message}}
