async function pollAdminJob(jobId){const out=$('#deployOutput');for(let i=0;i<1200;i++){const job=await api(`/api/admin/jobs/${jobId}`);out.textContent=JSON.stringify(job,null,2);if(['completed','failed'].includes(job.status))return job;await new Promise(resolve=>setTimeout(resolve,700))}throw new Error('Deployment job timeout')}
