function renderSystem(){const safe={product:status.product,product_family:status.product_family,edition:status.edition,locale:status.locale,version:status.version,auth_mode:status.auth_mode,registration_policy:status.registration_policy,bootstrap_model:status.bootstrap_model,setup_complete:status.setup_complete,routing:status.routing,provider_status:status.provider_status,support_email:status.support_email,support_inbox:status.support_inbox};$('#system').textContent=JSON.stringify(safe,null,2);$('#metricVersion').textContent=`v${status.version}`;$('#metricProviders').textContent=String((status.providers||[]).length);$('#setupSummary').textContent=status.setup_complete?adminText('Маршрутизация настроена и сохранена.','Routing is configured and persisted.'):adminText('Используется bootstrap-маршрут. Выберите production models из обнаруженного inventory.','The bootstrap route is in use. Select production models from the discovered inventory.')}
async function refreshLogs(){const out=$('#adminLogs'),audit=$('#adminAudit');if(!out)return;out.textContent=adminText('Загрузка…','Loading…');if(audit)audit.textContent=adminText('Загрузка…','Loading…');try{const params=new URLSearchParams({limit:'250'});const level=$('#logLevel')?.value||'',event=$('#logEvent')?.value.trim()||'',requestId=$('#logRequest')?.value.trim()||'',correlationId=$('#logCorrelation')?.value.trim()||'';if(level)params.set('level',level);if(event)params.set('event',event);if(requestId)params.set('request_id',requestId);if(correlationId)params.set('correlation_id',correlationId);const payload=await api('/api/admin/logs?'+params);out.textContent=(payload.events||[]).map(item=>`${item.timestamp||''} ${item.level||''} ${item.event||''} req=${item.request_id||'-'} corr=${item.correlation_id||'-'} ${item.status||''}`).join('\n')||adminText('Событий по фильтру нет.','No events match the filter.');if(audit){const auditPayload=await api('/api/admin/audit?limit=100'+(event?'&action='+encodeURIComponent(event):''));audit.textContent=(auditPayload.events||[]).map(item=>`${new Date(Number(item.created_at||0)*1000).toLocaleString('ru-RU')} ${item.action} ${JSON.stringify(item.details)}`).join('\n')||adminText('Audit-событий нет.','No audit events.')}}catch(error){out.textContent=error.message;if(audit)audit.textContent=error.message}}
