async function downloadDiagnostics(){const headers={};if(token)headers.Authorization='Bearer '+token;const response=await fetch('/api/admin/diagnostics/download',{headers,credentials:'same-origin'});if(!response.ok)throw new Error((await response.json().catch(()=>({}))).error||'Не удалось собрать диагностику');const blob=await response.blob();const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`personal-agent-diagnostics-${status.version||'current'}.zip`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}

function renderFeedbackItems(items){const host=$('#feedbackList');if(!host)return;clear(host);if(!items?.length){host.append(node('p','muted','Отзывов пока нет.'));return}for(const item of items){const card=node('article','feedback-admin-card');const top=node('div','provider-card-head');top.append(node('strong','',`${item.category}${item.rating?` · ${item.rating}/5`:''}`),node('span','provider-meta',new Date(Number(item.created_at||0)*1000).toLocaleString('ru-RU')));card.append(top,node('p','',item.message),node('small','muted',`user=${item.user_id} · ${item.page||'без страницы'} · ${item.status}`));host.append(card)}}
async function refreshAdminAuthStatus(){const host=$('#adminAuthStatus');if(!host)return;try{const value=await api('/api/admin/auth-status');if(value.auth_mode==='personal'){host.textContent=adminText('Локальный personal-режим: владелец этого ПК входит в Admin Console без токена. Break-glass нужен только как аварийный путь.','Local personal mode: the owner of this computer can enter Administration without a token. Break-glass is emergency access only.')}else if(value.account_admin){host.textContent=adminText('Аккаунт OWNER/ADMIN уже авторизован — используйте обычный вход без break-glass токена.','An OWNER/ADMIN account is already authenticated — use regular account access without the break-glass token.')}else if(value.break_glass_configured){host.textContent=adminText('Break-glass токен настроен. Используйте его только если обычный OWNER/ADMIN вход недоступен.','A break-glass token is configured. Use it only when regular OWNER/ADMIN access is unavailable.')}else{host.textContent=adminText('Break-glass токен не настроен. Войдите обычным OWNER/ADMIN аккаунтом; аварийный вход будет недоступен.','No break-glass token is configured. Sign in with a regular OWNER/ADMIN account; emergency access is unavailable.')}}catch(error){host.textContent=adminText('Не удалось определить способ администрирования: ','Could not determine the administration access method: ')+error.message}}
function configureProviderForm(){const preset=$('#providerPreset')?.value||'';const type=$('#providerType')?.value;if(preset==='openai_chatgpt'){if(!$('#providerName').value.trim())$('#providerName').value='OpenAI API';if($('#providerType'))$('#providerType').value='openai_responses';if($('#providerUrl'))$('#providerUrl').value='https://api.openai.com/v1';if($('#providerBillingClass'))$('#providerBillingClass').value='PLATFORM_REMOTE'}else if(preset==='gemini'){if(!$('#providerName').value.trim())$('#providerName').value='Gemini API';if($('#providerType'))$('#providerType').value='openai_compatible';if($('#providerUrl'))$('#providerUrl').value='https://generativelanguage.googleapis.com/v1beta/openai/';if($('#providerBillingClass'))$('#providerBillingClass').value='PLATFORM_REMOTE'}else if(preset==='anthropic'){if(!$('#providerName').value.trim())$('#providerName').value='Anthropic gateway';if($('#providerType'))$('#providerType').value='openai_compatible';if($('#providerUrl'))$('#providerUrl').value='https://api.anthropic.com/v1';if($('#providerBillingClass'))$('#providerBillingClass').value='PLATFORM_REMOTE'}else if(preset==='openrouter'){if(!$('#providerName').value.trim())$('#providerName').value='OpenRouter';if($('#providerType'))$('#providerType').value='openai_compatible';if($('#providerUrl'))$('#providerUrl').value='https://openrouter.ai/api/v1';if($('#providerBillingClass'))$('#providerBillingClass').value='PLATFORM_REMOTE'}else if(preset==='ollama'){if(!$('#providerName').value.trim())$('#providerName').value='Local Ollama';if($('#providerType'))$('#providerType').value='ollama';if($('#providerUrl'))$('#providerUrl').value='http://ollama:11434';if($('#providerBillingClass'))$('#providerBillingClass').value='BYOK'}if(type==='openai_responses'){if(!$('#providerName').value.trim())$('#providerName').value='OpenAI API';if(!$('#providerUrl').value.trim()||$('#providerUrl').value.includes('host.docker.internal'))$('#providerUrl').value='https://api.openai.com/v1';$('#providerBillingClass').value='PLATFORM_REMOTE'}else if(type==='ollama'){if(!$('#providerUrl').value.trim()||$('#providerUrl').value.includes('api.openai.com'))$('#providerUrl').value='http://ollama:11434';$('#providerBillingClass').value='BYOK'}else if(type==='openai_compatible'&&$('#providerUrl').value.includes('api.openai.com')){$('#providerUrl').value=''}}function renderAll(){renderProviders();renderModels();renderRoutes();renderSearchPolicy();renderSiteProfiles();renderUsers();renderBilling();renderDeployments();renderMonitoring();renderSystem();renderMailSettings()}
