const ADMIN_TOUR_STATE_KEY='par-admin-tour-state';
function adminTourState(){return localStorage.getItem(ADMIN_TOUR_STATE_KEY)||''}
function adminTourSetState(status){if(status)localStorage.setItem(ADMIN_TOUR_STATE_KEY,status);else localStorage.removeItem(ADMIN_TOUR_STATE_KEY)}
function adminTourPosition(){const step=ADMIN_TOUR_STEPS[adminTourIndex],target=document.querySelector(step?.selector||'');if(!target)return;target.scrollIntoView({block:'center'});requestAnimationFrame(()=>{const r=target.getBoundingClientRect(),spot=$('#adminTourSpotlight'),card=$('#adminTourCard');Object.assign(spot.style,{left:`${Math.max(4,r.left-7)}px`,top:`${Math.max(4,r.top-7)}px`,width:`${r.width+14}px`,height:`${r.height+14}px`});let left=r.right+18;if(left+360>innerWidth-14)left=Math.max(14,r.left-378);Object.assign(card.style,{left:`${left}px`,top:`${Math.max(14,Math.min(innerHeight-230,r.top))}px`})})}
function renderAdminTour(){const step=ADMIN_TOUR_STEPS[adminTourIndex];$('#adminTourProgress').textContent=adminLang()==='en'?`${adminTourIndex+1} of ${ADMIN_TOUR_STEPS.length}`:`${adminTourIndex+1} из ${ADMIN_TOUR_STEPS.length}`;$('#adminTourTitle').textContent=adminLang()==='en'?(step.title_en||step.title):step.title;$('#adminTourText').textContent=adminLang()==='en'?(step.text_en||step.text):step.text;$('#adminTourBack').disabled=adminTourIndex===0;$('#adminTourNext').textContent=adminTourIndex===ADMIN_TOUR_STEPS.length-1?adminText('Готово','Done'):adminText('Далее','Next');adminTourPosition()}
async function adminTourPersist(status){adminTourSetState(status);if(token)return;try{await api('/api/onboarding',{method:'POST',body:JSON.stringify({persona:'admin',status,current_step:adminTourIndex})})}catch(_){}}
async function startAdminTour(force=false){if(!force&&['completed','skipped'].includes(adminTourState()))return;if(!force&&!token){try{const current=await api('/api/onboarding?persona=admin');if(['completed','skipped'].includes(current.state?.status)){adminTourSetState(current.state.status);return}}catch(_){}}adminTourIndex=0;$('#adminTourLayer').hidden=false;adminTourPersist('in_progress');renderAdminTour()}
async function finishAdminTour(status){adminTourSetState(status);await adminTourPersist(status);$('#adminTourLayer').hidden=true}
async function maybeStartAdminTour(){if(['completed','skipped'].includes(adminTourState()))return;await startAdminTour(false)}

