$('#pullBtn').onclick=async()=>{const model=$('#pullModel').value.trim();const provider_id=$('#pullProvider').value;const output=$('#pullState');if(!model)return;$('#pullBtn').disabled=true;try{const job=await api('/api/admin/models/pull',{method:'POST',body:JSON.stringify({provider_id,model})});output.textContent=adminText('queued: 0% — В очереди','queued: 0% — In queue');output.className='job-state running';const timer=setInterval(async()=>{try{const result=await api(`/api/admin/jobs/${job.job_id}`);output.textContent=`${result.status}: ${result.progress}% — ${result.message||result.error||''}`;if(['completed','failed'].includes(result.status)){clearInterval(timer);$('#pullBtn').disabled=false;output.className=`job-state ${result.status}`;if(result.status==='completed'){await load();selectTab('models')}}}catch(error){clearInterval(timer);$('#pullBtn').disabled=false;output.textContent=error.message;output.className='job-state failed'}},500)}catch(error){$('#pullBtn').disabled=false;output.textContent=`${adminText('Ошибка','Error')}: ${error.message}`;output.className='job-state failed'}};
