function ensureSupportInboxPanel(){const feedbackTab=document.querySelector('[data-panel="feedback"]');if(!feedbackTab||$('#supportMailboxList'))return;const panel=node('div','panel');const heading=node('div','panel-heading');const left=node('div','');left.append(node('span','eyebrow','SUPPORT MAIL'),node('h2','',status?.support_email||'support@rodnoi-agent.ru'));const button=node('button','secondary-button',adminText('Обновить inbox','Refresh inbox'));button.type='button';button.onclick=()=>refreshSupportInbox();const meta=node('p','muted',adminText('Загрузка…','Loading…'));meta.id='supportMailboxMeta';const list=node('div','feedback-admin-list');list.id='supportMailboxList';heading.append(left,button);panel.append(heading,meta,list);feedbackTab.append(panel)}
function renderSupportInbox(payload){ensureSupportInboxPanel();const meta=$('#supportMailboxMeta'),host=$('#supportMailboxList');if(!meta||!host)return;clear(host);const inbox=payload?.inbox||status?.support_inbox||{};const email=payload?.support_email||status?.support_email||'support@rodnoi-agent.ru';const heading=meta.previousElementSibling?.querySelector('h2');if(heading)heading.textContent=email;meta.textContent=inbox.enabled?`${email} · ${adminText('непрочитано','unread')}: ${Number(inbox.unread||0)} · ${adminText('всего','total')}: ${Number(inbox.total||0)}`:adminText('Inbox поддержки ещё не готов: проверьте контейнер smtp и volume support-mail.','Support inbox is not ready yet: check the smtp container and the support-mail volume.');if(!payload?.items?.length){host.append(node('p','muted',adminText('Писем пока нет.','No messages yet.')));return}for(const item of payload.items){const card=node('article','feedback-admin-card');const top=node('div','provider-card-head');top.append(node('strong','',item.subject||adminText('(без темы)','(no subject)')),node('span','provider-meta',item.state||''));card.append(top,node('p','',item.preview||''),node('small','muted',`${item.from||'unknown'} → ${item.to||email} · ${new Date(Number(item.received_at||0)*1000).toLocaleString(adminLang()==='en'?'en-US':'ru-RU')}`));host.append(card)}}
async function refreshSupportInbox(){ensureSupportInboxPanel();const meta=$('#supportMailboxMeta'),host=$('#supportMailboxList');if(meta)meta.textContent=adminText('Загрузка…','Loading…');if(host)host.textContent='';try{supportInboxStatus=await api('/api/admin/support-inbox?limit=50');renderSupportInbox(supportInboxStatus)}catch(error){if(meta)meta.textContent=error.message}}
function mailField(id,labelRu,labelEn,type='text',rows=0,placeholder=''){const wrap=document.createElement('label');const title=document.createElement('span');title.textContent=adminText(labelRu,labelEn);wrap.append(title);const control=rows>0?document.createElement('textarea'):document.createElement('input');control.id=id;if(rows>0)control.rows=rows;else control.type=type;if(placeholder)control.placeholder=placeholder;wrap.append(control);return wrap}
function ensureMailSettingsPanel(){const feedbackTab=document.querySelector('[data-panel="feedback"]');if(!feedbackTab||$('#mailSettingsForm'))return;const panel=node('div','panel');const heading=node('div','panel-heading');const left=node('div','');left.append(node('span','eyebrow','EMAIL & SUPPORT'),node('h2','',adminText('Почта и поддержка','Mail and support')));const summary=node('p','muted',adminText('Оформление писем, адрес поддержки и тестовая отправка меняются здесь без деплоя. SMTP в env остаётся транспортом доставки.','Configure email appearance, support address and test delivery here without redeploying. SMTP in env remains the transport layer.'));summary.id='mailSettingsSummary';heading.append(left);panel.append(heading,summary);const form=node('div','provider-form');form.id='mailSettingsForm';form.append(mailField('mailProductName','Название продукта','Product name'),mailField('mailSupportEmail','Почта поддержки','Support email','email'),mailField('mailSupportName','Имя поддержки','Support name'),mailField('mailSenderEmail','Email отправителя','Sender email','email'),mailField('mailSenderName','Имя отправителя','Sender name'),mailField('mailReplyToEmail','Reply-To email','Reply-To email','email'),mailField('mailPublicBaseUrl','Публичный URL','Public base URL','url',0,'https://rodnoi-agent.ru'),mailField('mailFooterText','Текстовый footer','Plain-text footer','text',4),mailField('mailFooterHtml','HTML footer','HTML footer','text',8),mailField('mailVerifySubject','Тема подтверждения','Verification subject'),mailField('mailVerifyText','Текст подтверждения','Verification text','text',8),mailField('mailVerifyHtml','HTML подтверждения','Verification HTML','text',10),mailField('mailResetSubject','Тема сброса пароля','Password reset subject'),mailField('mailResetText','Текст сброса пароля','Password reset text','text',8),mailField('mailResetHtml','HTML сброса пароля','Password reset HTML','text',10));const vars=node('div','info-callout',adminText('Переменные шаблонов: {product_name}, {support_email}, {support_name}, {sender_name}, {sender_email}, {reply_to_email}, {url}, {expires_at_utc}, {action}, {year}.','Template variables: {product_name}, {support_email}, {support_name}, {sender_name}, {sender_email}, {reply_to_email}, {url}, {expires_at_utc}, {action}, {year}.'));const actions=node('div','panel-actions');const save=node('button','primary-button',adminText('Сохранить почтовые настройки','Save mail settings'));save.type='button';save.onclick=()=>saveMailSettings();const test=node('button','secondary-button',adminText('Отправить тест','Send test'));test.type='button';test.onclick=()=>sendMailSettingsTest();actions.append(save,test);const testForm=node('div','provider-form');testForm.style.marginTop='16px';testForm.append(mailField('mailTestRecipient','Тестовый email','Test email','email'),(()=>{const label=document.createElement('label');const span=document.createElement('span');span.textContent=adminText('Тип письма','Email type');const select=document.createElement('select');select.id='mailTestKind';for(const item of [{value:'verify',ru:'Подтверждение email',en:'Verify email'},{value:'reset',ru:'Сброс пароля',en:'Password reset'}]){const option=document.createElement('option');option.value=item.value;option.textContent=adminText(item.ru,item.en);select.append(option)}label.append(span,select);return label})());const state=node('p','job-state');state.id='mailSettingsState';panel.append(form,vars,actions,testForm,state);feedbackTab.insertBefore(panel,feedbackTab.firstChild)}
function collectMailSettings(){return{product_name:$('#mailProductName')?.value.trim()||'',support_email:$('#mailSupportEmail')?.value.trim()||'',support_name:$('#mailSupportName')?.value.trim()||'',sender_email:$('#mailSenderEmail')?.value.trim()||'',sender_name:$('#mailSenderName')?.value.trim()||'',reply_to_email:$('#mailReplyToEmail')?.value.trim()||'',public_base_url:$('#mailPublicBaseUrl')?.value.trim()||'',footer_text:$('#mailFooterText')?.value||'',footer_html:$('#mailFooterHtml')?.value||'',templates:{verify:{subject:$('#mailVerifySubject')?.value.trim()||'',text:$('#mailVerifyText')?.value||'',html:$('#mailVerifyHtml')?.value||''},reset:{subject:$('#mailResetSubject')?.value.trim()||'',text:$('#mailResetText')?.value||'',html:$('#mailResetHtml')?.value||''}}}}
function renderMailSettings(){ensureMailSettingsPanel();if(!emailSettings)return;const summary=$('#mailSettingsSummary');if(summary)summary.textContent=`${adminText('Отправитель','Sender')}: ${emailSettings.sender_email||status?.support_email||'—'} · ${adminText('поддержка','support')}: ${emailSettings.support_email||status?.support_email||'—'}`;const mapping={mailProductName:emailSettings.product_name,mailSupportEmail:emailSettings.support_email,mailSupportName:emailSettings.support_name,mailSenderEmail:emailSettings.sender_email,mailSenderName:emailSettings.sender_name,mailReplyToEmail:emailSettings.reply_to_email,mailPublicBaseUrl:emailSettings.public_base_url,mailFooterText:emailSettings.footer_text,mailFooterHtml:emailSettings.footer_html,mailVerifySubject:emailSettings.templates?.verify?.subject,mailVerifyText:emailSettings.templates?.verify?.text,mailVerifyHtml:emailSettings.templates?.verify?.html,mailResetSubject:emailSettings.templates?.reset?.subject,mailResetText:emailSettings.templates?.reset?.text,mailResetHtml:emailSettings.templates?.reset?.html};for(const [id,value] of Object.entries(mapping)){const el=$('#'+id);if(el&&document.activeElement!==el)el.value=value||''}}
async function saveMailSettings(){const out=$('#mailSettingsState');if(out){out.textContent='';out.className='job-state running'}try{const payload=await api('/api/admin/email-settings',{method:'POST',body:JSON.stringify(collectMailSettings())});emailSettings=payload.settings||null;if(status&&emailSettings?.support_email)status.support_email=emailSettings.support_email;renderMailSettings();if(out){out.textContent=adminText('Почтовые настройки сохранены.','Mail settings saved.');out.className='job-state completed'}}catch(error){if(out){out.textContent=error.message;out.className='job-state failed'}}}
async function sendMailSettingsTest(){const out=$('#mailSettingsState');if(out){out.textContent=adminText('Отправляю тестовое письмо…','Sending test email…');out.className='job-state running'}try{const recipient=$('#mailTestRecipient')?.value.trim()||'';const kind=$('#mailTestKind')?.value||'verify';const payload=await api('/api/admin/email-settings/test',{method:'POST',body:JSON.stringify({recipient,kind})});if(out){out.textContent=payload.delivered?adminText('Тестовое письмо отправлено.','Test email sent.'):adminText('SMTP не отправил письмо.','SMTP did not send the message.');out.className=payload.delivered?'job-state completed':'job-state failed'}}catch(error){if(out){out.textContent=error.message;out.className='job-state failed'}}}
async function refreshFeedback(){const host=$('#feedbackList');if(host)host.textContent=adminText('Загрузка…','Loading…');ensureMailSettingsPanel();ensureSupportInboxPanel();try{const [payload,supportPayload,mailPayload]=await Promise.all([api('/api/admin/feedback'),api('/api/admin/support-inbox?limit=50'),api('/api/admin/email-settings')]);supportInboxStatus=supportPayload;emailSettings=mailPayload.settings||emailSettings;if(status&&emailSettings?.support_email)status.support_email=emailSettings.support_email;renderFeedbackItems(payload.items||[]);renderMailSettings();renderSupportInbox(supportPayload)}catch(error){if(host)host.textContent=error.message;const meta=$('#supportMailboxMeta');if(meta)meta.textContent=error.message;const state=$('#mailSettingsState');if(state)state.textContent=error.message}}
